/**
 * Client-side data export.
 *
 * CSV is generated by hand rather than pulled in as a dependency — the escape
 * rules are short and it keeps the bundle lean. "PDF" export opens a styled
 * print view and delegates to the browser's own print-to-PDF, which avoids
 * shipping a ~500 KB PDF renderer for a feature used occasionally.
 */

export interface ExportColumn<T> {
  header: string;
  value: (item: T) => string | number;
}

/**
 * Escapes a CSV field per RFC 4180: wrap in quotes if it contains a comma,
 * quote or newline, and double any embedded quotes.
 */
function escapeCsv(value: string | number): string {
  const str = String(value ?? '');

  // A leading =, +, - or @ makes spreadsheet software treat the cell as a
  // formula. Prefixing with a single quote neutralises that.
  const guarded = /^[=+\-@\t\r]/.test(str) ? `'${str}` : str;

  if (/[",\n\r]/.test(guarded)) {
    return `"${guarded.replace(/"/g, '""')}"`;
  }
  return guarded;
}

export function toCsv<T>(rows: readonly T[], columns: ExportColumn<T>[]): string {
  const header = columns.map((c) => escapeCsv(c.header)).join(',');
  const body = rows.map((row) => columns.map((c) => escapeCsv(c.value(row))).join(','));
  return [header, ...body].join('\r\n');
}

/** Triggers a browser download of the given text content. */
export function downloadFile(filename: string, content: string, mimeType: string): void {
  if (typeof window === 'undefined') return;

  // BOM so Excel opens UTF-8 CSVs without mangling non-ASCII names.
  const blob = new Blob([mimeType.includes('csv') ? '﻿' + content : content], {
    type: `${mimeType};charset=utf-8`,
  });

  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  // Revoking immediately can cancel the download in some browsers.
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export function exportCsv<T>(
  filename: string,
  rows: readonly T[],
  columns: ExportColumn<T>[],
): void {
  downloadFile(`${filename}.csv`, toCsv(rows, columns), 'text/csv');
}

/**
 * Opens a print-ready window containing the given rows.
 * The user chooses "Save as PDF" in the print dialog.
 */
export function exportPdf<T>(
  title: string,
  rows: readonly T[],
  columns: ExportColumn<T>[],
  meta?: string,
): boolean {
  if (typeof window === 'undefined') return false;

  const printWindow = window.open('', '_blank', 'width=1024,height=768');
  // Popup blocked — the caller surfaces this as a toast.
  if (!printWindow) return false;

  const head = columns.map((c) => `<th>${escapeHtml(c.header)}</th>`).join('');
  const body = rows
    .map(
      (row) =>
        `<tr>${columns.map((c) => `<td>${escapeHtml(String(c.value(row)))}</td>`).join('')}</tr>`,
    )
    .join('');

  printWindow.document.write(`<!doctype html>
<html>
<head>
  <meta charset="utf-8" />
  <title>${escapeHtml(title)}</title>
  <style>
    * { box-sizing: border-box; }
    body { font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; color: #0f172a; margin: 32px; }
    header { border-bottom: 2px solid #1e40af; padding-bottom: 16px; margin-bottom: 24px; }
    h1 { margin: 0 0 4px; font-size: 20px; color: #1e3a8a; }
    .meta { color: #64748b; font-size: 12px; }
    table { width: 100%; border-collapse: collapse; font-size: 11px; }
    th { background: #f1f5f9; text-align: left; padding: 8px; border-bottom: 2px solid #cbd5e1; font-weight: 600; }
    td { padding: 7px 8px; border-bottom: 1px solid #e2e8f0; }
    tr:nth-child(even) td { background: #f8fafc; }
    footer { margin-top: 24px; font-size: 10px; color: #94a3b8; text-align: center; }
    @media print { body { margin: 12mm; } thead { display: table-header-group; } }
  </style>
</head>
<body>
  <header>
    <h1>${escapeHtml(title)}</h1>
    <div class="meta">${escapeHtml(meta ?? '')} · ${rows.length} record${rows.length === 1 ? '' : 's'} · Generated ${new Date().toLocaleString()}</div>
  </header>
  <table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>
  <footer>NorthBank — Management Console. This document is generated from demo data.</footer>
</body>
</html>`);

  printWindow.document.close();
  printWindow.focus();

  // Give the document a tick to lay out before invoking print.
  setTimeout(() => printWindow.print(), 350);
  return true;
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
